     public function failed(): void
     {
-        Http::asJson()
-            ->withToken((string) config('services.billinghub.key', 'test'))
-            ->post('https://api.billinghub.example/v1/refunds', [
+        $this->refundIfNeeded();
+    }
+
+    private function refundIfNeeded(): void
+    {
+        DB::transaction(function (): void {
+            // Lock the subscription row so concurrent settlement attempts cannot
+            // both observe an empty ledger and issue a refund.
+            Subscription::query()
+                ->whereKey($this->subscription->id)
+                ->lockForUpdate()
+                ->firstOrFail();
+
+            $alreadyRefunded = LedgerEntry::query()
+                ->where('subscription_id', $this->subscription->id)
+                ->where('kind', LedgerEntry::KIND_REFUND)
+                ->lockForUpdate()
+                ->exists();
+
+            if ($alreadyRefunded) {
+                return;
+            }
+
+            $refund = Http::asJson()
+                ->withToken((string) config('services.billinghub.key', 'test'))
+                ->post('https://api.billinghub.example/v1/refunds', [
+                    'subscription_id' => $this->subscription->id,
+                ]);
+
+            $refund->throw();
+
+            LedgerEntry::create([
                 'subscription_id' => $this->subscription->id,
+                'kind' => LedgerEntry::KIND_REFUND,
+                'amount_cents' => (int) $refund->json('amount_cents'),
             ]);
-
